            },
            json: true,
            timeout: 10000
        });

        const history = {};
        if (result.values && result.values.length > 1) {
            const header = result.values[0];
            const emailIndex = header.indexOf('email');
            const lastSentIndex = header.indexOf('lastSent');
            const statusIndex = header.indexOf('status');
            const repliedIndex = header.indexOf('replied');
            const campaignIndex = header.indexOf('campaign');

            if (emailIndex !== -1 && lastSentIndex !== -1) {
                for (let i = 1; i < result.values.length; i++) {
                    const row = result.values[i];
                    if (row[emailIndex] && row[lastSentIndex]) {
                        const email = String(row[emailIndex]).toLowerCase().trim();
