rder:0;border-top:1px solid #e2e8f0;margin:22px 0;"><p style="margin:0;color:#0f172a;font-size:14px;line-height:1.6;"><strong>${escapeHtml(cfg.company.senderName)}</strong><br>${escapeHtml(cfg.company.senderTitle)} · ${escapeHtml(cfg.company.legalName||cfg.company.name)}<br><a href="${escapeHtml(cfg.company.website||'https://srlines.net')}" style="color:${brand.primary||'#16A34A'};text-decoration:none;">${escapeHtml(cfg.company.website||'https://srlines.net')}</a></p></div></td></tr></table></td></tr></table></body></html>`; }
for (const r of rows) {
 const email = String(r.email || '').toLowerCase().trim(); if (!email) continue;
 const t = new Date(r.lastSent || r.timestamp || 0).getTime();
