const cfg = $('Runtime Config').first().json;
function header(m, name){ const h=(m.payload?.headers||[]).find(x=>String(x.name).toLowerCase()===name.toLowerCase()); return h?.value || ''; }
const textOf = m => [m.snippet, header(m,'To'), header(m,'X-Failed-Recipients'), header(m,'Final-Recipient'), header(m,'Original-Recipient'), header(m,'Subject')].filter(Boolean).join(' ');
const seen=new Set(), out=[];
for (const item of items) { const m=item.json; const text=textOf(m); const emails=[...text.matchAll(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig)].map(x=>x[0].toLowerCase()).filter(e=>!e.includes('mailer-daemon')&&!e.includes('postmaster')); for (const email of emails) { if(seen.has(email)) continue; seen.add(email); out.push({json:{timestamp:new Date().toISOString(),type:'email',value:email,source:'gmail_bounce_search',reason:'hard_or_soft_bounce_detected',notes:`Thread ${m.threadId||m.id||''}`}}); } }
