const cfg = $('Runtime Config').first().json;
async function sheetSet(tab, col){ try{ const res=await this.helpers.httpRequest({method:'GET',url:`https://sheets.googleapis.com/v4/spreadsheets/${cfg.sheets.documentId}/values/${tab}`,headers:{Authorization:'Bearer '+(await this.helpers.getCredentials('googleSheetsOAuth2Api')).access_token},json:true,timeout:10000}); const vals=res.values||[]; if(vals.length<2) return new Set(); const idx=vals[0].indexOf(col); if(idx<0) return new Set(); return new Set(vals.slice(1).map(r=>String(r[idx]||'').toLowerCase().trim()).filter(Boolean)); }catch(e){ console.log(`Could not read ${tab}:`, e.message); return new Set(); }}
const replies=await sheetSet.call(this,cfg.sheets.replyLog,'email'); const blacklist=await sheetSet.call(this,cfg.sheets.blacklist,'value');
const inRun=new Set(); const out=[];
for(const item of items){ const j=item.json; const email=String(j.email||'').toLowerCase().trim(); if(!email||inRun.has(email)||replies.has(email)||blacklist.has(email)) continue; inRun.add(email); out.push({json:{...j,email,shouldSend:true}}); }
return out;
